import{_ as t,o as d,c as o,a2 as r}from"./chunks/framework.CeXt7FPx.js";const p=JSON.parse('{"title":"Environment variables","description":"","frontmatter":{},"headers":[],"relativePath":"reference/environment.md","filePath":"reference/environment.md"}'),a={name:"reference/environment.md"};function i(n,e,s,c,f,h){return d(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment variables&quot;">​</a></h1><p>Tiffin needs none of these. They&#39;re for moving a port another program holds, a second, separate Tiffin (tests, a portable install) or a registry of your own. Set them where tiffind starts (your shell, or the login item), then <code>tiffin stop</code>: it starts again with them on the next command.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>What</th></tr></thead><tbody><tr><td><code>TIFFIN_HOME</code></td><td>your system&#39;s folders (<a href="/tiffin/reference/files">Files and ports</a>)</td><td>One folder for all of Tiffin&#39;s data, settings and logs: a separate Tiffin.</td></tr><tr><td><code>TIFFIN_DNS_ADDR</code></td><td><code>127.0.53.1:53</code> (Windows, Linux), <code>127.0.0.1:1053</code> (macOS)</td><td>Where tiffind answers <code>.test</code> names: a loopback <code>ip:port</code>. On Linux, before <code>tiffin elevate</code>, it falls back to <code>127.0.0.1:1053</code>.</td></tr><tr><td><code>TIFFIN_HTTP_ADDR</code></td><td>port 80, else 8080, on <code>127.0.0.1</code> and <code>::1</code></td><td>Where sites are served over HTTP: one loopback <code>ip:port</code>.</td></tr><tr><td><code>TIFFIN_HTTPS_ADDR</code></td><td>port 443, else 8443</td><td>The same for HTTPS.</td></tr><tr><td><code>TIFFIN_SMTP_ADDR</code></td><td><code>127.0.0.1:2525</code></td><td>Where <a href="/tiffin/guide/mail">mail</a> is caught. PHP is pointed at it by itself.</td></tr><tr><td><code>TIFFIN_DUMPS_ADDR</code></td><td><code>127.0.0.1:9913</code></td><td>Where the Laravel package sends <a href="/tiffin/guide/dumps">dumps and queries</a>. Sites Tiffin serves get it through their environment.</td></tr><tr><td><code>TIFFIN_REGISTRY_URL</code></td><td>Tiffin&#39;s registry</td><td>Where packages come from. Only registries signed with a key built into Tiffin are accepted; there is no way to add a key at run time.</td></tr><tr><td><code>TIFFIN_OFFLINE</code></td><td>unset</td><td><code>1</code>: never fetch the package list; use the copy Tiffin has.</td></tr><tr><td><code>TIFFIN_NO_UPDATE_CHECK</code></td><td>unset</td><td><code>1</code>: tiffind doesn&#39;t look for a new Tiffin once a day. <code>tiffin self-update</code> still checks when asked.</td></tr><tr><td><code>TIFFIN_NO_AUTOSTART</code></td><td>unset</td><td><code>1</code>: <code>tiffin</code> commands don&#39;t start tiffind when it isn&#39;t running.</td></tr><tr><td><code>TIFFIN_DAEMON</code></td><td>the <code>tiffind</code> beside <code>tiffin</code></td><td>The tiffind to start: an absolute path.</td></tr><tr><td><code>TIFFIN_TRANSPORT</code></td><td><code>pipe</code> (Windows), <code>unix</code> (others)</td><td>How <code>tiffin</code> and the app reach tiffind: a named pipe or a Unix socket.</td></tr><tr><td><code>TIFFIN_ALLOW_ELEVATED</code></td><td>unset</td><td><code>1</code>: let tiffind run as root or administrator. Only for CI machines that run everything that way; never on your own computer.</td></tr></tbody></table><p>The DNS, SMTP and dumps addresses can also be saved with <code>tiffin config set</code>; a variable that is set wins over the saved address.</p><p>Ports must be on a loopback address (<code>127.x.x.x</code> or <code>::1</code>): Tiffin never listens on your network.</p><h2 id="set-by-tiffin-for-your-app" tabindex="-1">Set by Tiffin, for your app <a class="header-anchor" href="#set-by-tiffin-for-your-app" aria-label="Permalink to &quot;Set by Tiffin, for your app&quot;">​</a></h2><p>Not for you to set: Tiffin gives these to PHP for each request.</p><table tabindex="0"><thead><tr><th>Variable</th><th>What</th></tr></thead><tbody><tr><td><code>TIFFIN_REQUEST_ID</code></td><td>The proxy&#39;s id for this request (16 hex digits). The Laravel package files the request&#39;s dumps under it, which links them to the request the proxy kept, for <a href="/tiffin/guide/dumps#sending-a-request-again">sending it again</a>. A server variable: a request header can&#39;t set it.</td></tr></tbody></table><p>For the Laravel package, <code>TIFFIN_ENABLED=false</code> in an app&#39;s <code>.env</code> turns it off (see <a href="/tiffin/guide/dumps">Dumps and queries</a>).</p>',9)])])}const u=t(a,[["render",i]]);export{p as __pageData,u as default};
